const carrossel=document.querySelector('[data-carrossel]');if(carrossel){const slides=Array.from(carrossel.querySelectorAll('[data-slide]'));const pontos=Array.from(carrossel.querySelectorAll('[data-ponto]'));const contador=carrossel.querySelector('[data-contador]');const INTERVALO=6000;const carregarFundosOciosos=()=>{carrossel.querySelectorAll('[data-bg]').forEach((fundo)=>{fundo.style.backgroundImage=`url('${fundo.dataset.bg}')`;fundo.removeAttribute('data-bg');});};if(document.readyState==='complete')carregarFundosOciosos();else window.addEventListener('load',carregarFundosOciosos);let atual=0;let timer=null;const saidas=new Map();const ir=(i,direcao)=>{const anterior=atual;atual=(i+slides.length)%slides.length;const trocou=atual!==anterior;if(trocou){slides[atual].classList.remove('is-saindo');carrossel.dataset.direcao=direcao||(atual>anterior?'frente':'tras');void carrossel.offsetWidth;}slides.forEach((s,k)=>{const ativo=k===atual;s.classList.toggle('is-ativo',ativo);if(trocou&&k===anterior){s.classList.add('is-saindo');clearTimeout(saidas.get(s));saidas.set(s,setTimeout(()=>s.classList.remove('is-saindo'),700));}else if(!ativo){s.classList.remove('is-saindo');}s.setAttribute('aria-hidden',String(!ativo));s.querySelectorAll('a, button').forEach((f)=>{if(ativo)f.removeAttribute('tabindex');else f.setAttribute('tabindex','-1');});});pontos.forEach((p,k)=>{p.classList.toggle('is-ativo',k===atual);p.setAttribute('aria-current',k===atual?'true':'false');});if(contador)contador.textContent=(atual+1)+' / '+slides.length;};const parar=()=>{if(timer){clearInterval(timer);timer=null;}};const tocar=()=>{parar();if(reduzMovimento.matches)return;timer=setInterval(()=>ir(atual+1,'frente'),INTERVALO);};const prev=carrossel.querySelector('[data-prev]');const next=carrossel.querySelector('[data-next]');if(prev)prev.addEventListener('click',()=>{ir(atual-1,'tras');tocar();});if(next)next.addEventListener('click',()=>{ir(atual+1,'frente');tocar();});pontos.forEach((p,k)=>p.addEventListener('click',()=>{ir(k);tocar();}));carrossel.addEventListener('mouseenter',parar);carrossel.addEventListener('mouseleave',tocar);carrossel.addEventListener('focusin',parar);carrossel.addEventListener('focusout',tocar);document.addEventListener('visibilitychange',()=>(document.hidden?parar():tocar()));reduzMovimento.addEventListener('change',tocar);carrossel.addEventListener('keydown',(e)=>{if(e.key==='ArrowLeft'){ir(atual-1,'tras');tocar();}
if(e.key==='ArrowRight'){ir(atual+1,'frente');tocar();}});let x0=null,y0=null;carrossel.addEventListener('touchstart',(e)=>{x0=e.touches[0].clientX;y0=e.touches[0].clientY;},{passive:true});carrossel.addEventListener('touchend',(e)=>{if(x0===null)return;const dx=e.changedTouches[0].clientX-x0;const dy=e.changedTouches[0].clientY-y0;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)){ir(atual+(dx<0?1:-1),dx<0?'frente':'tras');tocar();}
x0=y0=null;},{passive:true});ir(0);tocar();}
document.querySelectorAll('[data-faq]').forEach((faq)=>{const abrir=(item,aberto)=>{const resposta=item.querySelector('.faq__resposta');const botao=item.querySelector('.faq__pergunta');item.classList.toggle('is-aberto',aberto);botao.setAttribute('aria-expanded',String(aberto));resposta.style.maxHeight=aberto?resposta.scrollHeight+'px':'';};faq.querySelectorAll('.faq__pergunta').forEach((botao)=>{botao.addEventListener('click',()=>{const item=botao.closest('.faq__item');const abrindo=!item.classList.contains('is-aberto');faq.querySelectorAll('.faq__item.is-aberto').forEach((o)=>o!==item&&abrir(o,false));abrir(item,abrindo);});});let t;window.addEventListener('resize',()=>{clearTimeout(t);t=setTimeout(()=>{faq.querySelectorAll('.faq__item.is-aberto').forEach((item)=>{item.querySelector('.faq__resposta').style.maxHeight=item.querySelector('.faq__resposta').scrollHeight+'px';});},150);});});const filtros=document.querySelector('[data-filtros]');if(filtros){const itens=Array.from(document.querySelectorAll('[data-linha]'));filtros.addEventListener('click',(e)=>{const botao=e.target.closest('.filtro');if(!botao)return;filtros.querySelectorAll('.filtro').forEach((b)=>{const ativo=b===botao;b.classList.toggle('is-ativo',ativo);b.setAttribute('aria-pressed',String(ativo));});const alvo=botao.dataset.filtro;itens.forEach((item)=>{item.hidden=!(alvo==='todas'||item.dataset.linha===alvo);});document.dispatchEvent(new Event('galeria:atualizar'));});}
document.querySelectorAll('[data-foto]').forEach((img)=>{const falhou=()=>{const foto=img.closest('.linha-card__foto');if(foto)foto.classList.add('sem-foto');img.remove();};img.addEventListener('error',falhou);if(img.complete&&img.naturalWidth===0)falhou();});const alvos=document.querySelectorAll('.revela');if(alvos.length){if(!('IntersectionObserver'in window)||reduzMovimento.matches){alvos.forEach((el)=>el.classList.add('is-visivel'));}else{const obs=new IntersectionObserver((entradas)=>{entradas.forEach((entrada)=>{if(!entrada.isIntersecting)return;entrada.target.classList.add('is-visivel');obs.unobserve(entrada.target);});},{threshold:0.1,rootMargin:'0px 0px -60px 0px'});alvos.forEach((el,i)=>{el.style.setProperty('--revela-atraso',(i%4)*65+'ms');obs.observe(el);});setTimeout(()=>alvos.forEach((el)=>el.classList.add('is-visivel')),2500);}}
